package com.openggf.game.soniccd.player;
import com.openggf.game.soniccd.CdReleaseVariant;
import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.media.CdProgramAssets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
class TestCdSharedKillPlayerLive {
 private CdPlayerTouchResponse.Actor actor(boolean rolling){return new CdPlayerTouchResponse.Actor(new CdPlayerMotionState(0x801357,0x600ABCD,0x123,-0x45,0x500,2,0x10,rolling?4:0,0xA4,7,14,0,0,1,7,0,0,0,0x12,0x34),0x234,2,10,0x45);}
 @Test void liveRollingCallsAbThen93AtTheExactSamePureKernelValues(){var a=actor(true);Object key=new Object();var sounds=new ArrayList<CdPlayerTouchResponse.FmSound>();var last=new CdPlayerTouchResponse.Actor[]{a};var out=CdPlayerTouchResponse.visitKillPlayer(a,1,0,7,0,key,s->{s.claim(key);sounds.add(s.sound());last[0]=s.actor();});assertEquals(CdPlayerTouchResponse.killPlayer(a,1,0,7,0),out);assertEquals(List.of(CdPlayerTouchResponse.FmSound.FM_CHARGESTOP,CdPlayerTouchResponse.FmSound.FM_HURT),sounds);assertEquals(out.actor(),last[0]);}
 @Test void abFailureKeepsResetPrefixBeforeJumpScoreAndDeathSuffix(){var a=actor(true);var fault=new IllegalArgumentException("FM AB");Object key=new Object();var prefix=new CdPlayerTouchResponse.Actor[]{a};var sounds=new ArrayList<CdPlayerTouchResponse.FmSound>();assertSame(fault,assertThrows(IllegalArgumentException.class,()->CdPlayerTouchResponse.visitKillPlayer(a,1,0,7,0,key,s->{s.claim(key);prefix[0]=s.actor();assertEquals(0,s.invincible());assertEquals(7,s.scoreChain());sounds.add(s.sound());throw fault;})));assertEquals(List.of(CdPlayerTouchResponse.FmSound.FM_CHARGESTOP),sounds);assertEquals(6,prefix[0].motion().routine());assertEquals(1,prefix[0].motion().playerJump());assertNotEquals(-0x700,prefix[0].motion().yVelocity());}
 @Test void sound93FailureKeepsEveryDeathStoreAndNeverReturnsAResult(){var a=actor(true);var fault=new IllegalArgumentException("FM93");Object key=new Object();var prefix=new CdPlayerTouchResponse.Actor[]{a};var sounds=new ArrayList<CdPlayerTouchResponse.FmSound>();assertSame(fault,assertThrows(IllegalArgumentException.class,()->CdPlayerTouchResponse.visitKillPlayer(a,1,0,7,0,key,s->{s.claim(key);prefix[0]=s.actor();sounds.add(s.sound());if(s.sound()==CdPlayerTouchResponse.FmSound.FM_HURT){assertEquals(0,s.scoreChain());throw fault;}})));assertEquals(2,sounds.size());assertEquals(-0x700,prefix[0].motion().yVelocity());assertEquals(0,prefix[0].motion().xVelocity());assertEquals(0,prefix[0].motion().playerJump());assertEquals(0,prefix[0].priority());}
 @Test void debugNonzeroIsAnExactNoWriteNoSoundReturn(){var a=actor(true);var out=CdPlayerTouchResponse.visitKillPlayer(a,1,1,7,0,new Object(),s->fail("debug no sound"));assertSame(a,out.actor());assertEquals(1,out.invincible());assertEquals(7,out.scoreChain());assertTrue(out.calls().isEmpty());}
 @Test void privateStepsRejectRepeatedForeignAndExpiredClaims(){Object key=new Object();var saved=new CdPlayerTouchResponse.KillStep[1];CdPlayerTouchResponse.visitKillPlayer(actor(false),1,0,7,0,key,s->{saved[0]=s;assertThrows(IllegalStateException.class,()->s.claim(new Object()));s.claim(key);assertThrows(IllegalStateException.class,()->s.claim(key));});assertThrows(IllegalStateException.class,()->saved[0].claim(key));}
 private CdStagePlayerSource source()throws Exception{String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank());Path cue;try(var p=Files.list(Path.of(root).resolve("USA"))){var v=p.filter(x->x.toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,v.size());cue=v.getFirst();}try(var a=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){return CdStagePlayerSource.fromProgramme(a,CdR4DataLayout.Programme.R41A.payload().stage());}}
 @Test void directLiveBodyAbFailureRetainsSourcePrefixAndNoLaterBodyWork()throws Exception{var h=new H(source(),0xAB);assertSame(h.fault,assertThrows(IllegalArgumentException.class,h.v::run));assertEquals(List.of(0xAB),h.sounds);assertEquals(6,h.v.state.motion().routine());assertEquals(1,h.v.state.motion().playerJump());assertEquals(7,h.v.environment.movement().globals().scoreChain());assertFalse(h.v.events.stream().anyMatch(x->x.startsWith("completed:")));}
 @Test void directLiveBody93FailureRetainsDeathAndOriginalException()throws Exception{var h=new H(source(),0x93);assertSame(h.fault,assertThrows(IllegalArgumentException.class,h.v::run));assertEquals(List.of(0xAB,0x93),h.sounds);assertEquals(-0x700,h.v.state.motion().yVelocity());assertEquals(0,h.v.state.motion().playerJump());assertEquals(0,h.v.environment.movement().globals().scoreChain());assertFalse(h.v.events.contains("draw"));}
 @Test void hurtRepeatedNativeKillsAreNotDeduplicated()throws Exception{var h=new H(source(),-1);h.v.run();assertEquals(List.of(0xAB,0x93,0x93),h.sounds);assertTrue(h.v.events.contains("completed:HURT_RETURN"));}
 static final class H implements CdPlayerSemanticRuntime.Ports {
  final TestCdOriginalPlayerSemanticRuntime.Harness v;final int failId;final IllegalArgumentException fault=new IllegalArgumentException("actual live sound failure");final List<Integer> sounds=new ArrayList<>();
  H(CdStagePlayerSource s,int failId){this.failId=failId;v=new TestCdOriginalPlayerSemanticRuntime.Harness(s);var init=CdPlayerBody.forOriginalLoading(s).step(v.state,v.environment);v.state=init.state();v.environment=init.environment();v.routine(4);v.flags(4);v.jump(1);v.y(0x600);var e=v.environment;var m=e.movement();var g=m.globals();v.environment=new CdPlayerBody.Environment(new CdPlayerMovement.Environment(m.physics(),m.bounds(),m.gates(),new CdPlayerMovement.Globals(g.lookMode(),g.cameraYCentre(),g.primaryAngle(),g.secondaryAngle(),g.boredTimer(),7,g.debugAngle(),g.debugAngleShift(),g.debugQuadrant(),g.debugFloorDistance())),e.controls(),e.globals(),e.dynamicSlots());v.runtime=CdPlayerSemanticRuntime.fromOriginalProgramme(s,this);v.body=CdPlayerBody.fromOriginalProgramme(s,v.runtime);}
  public long generation(){return v.generation();}public void requireCurrent(CdPlayerSemanticRuntime.Call c){v.requireCurrent(c);}public CdPlayerBody.State state(CdPlayerSemanticRuntime.Call c){return v.state(c);}public CdPlayerBody.Environment environment(CdPlayerSemanticRuntime.Call c){return v.environment(c);}public void publish(CdPlayerSemanticRuntime.Call c,CdPlayerBody.State s,CdPlayerBody.Environment e,CdPlayerBody.State n,CdPlayerBody.Environment ne){v.publish(c,s,e,n,ne);}
  public Optional<CdPlayerMovement.ObjectContext> objects(CdPlayerSemanticRuntime.Call c){return v.objects(c);}public void flipperAnimation(CdPlayerSemanticRuntime.Call c,CdPlayerMovement.SlotPatch p){v.flipperAnimation(c,p);}public CdR4WaterAirPorts.Calls water(CdPlayerSemanticRuntime.Call c){return v.water(c);}public void draw(CdPlayerSemanticRuntime.Call c){v.draw(c);}public void sound(CdPlayerSemanticRuntime.Call c,int id){sounds.add(id);if(id==failId)throw fault;v.sound(c,id);}public void restoreStageMusic(CdPlayerSemanticRuntime.Call c){v.restoreStageMusic(c);}public void collideObjects(CdPlayerSemanticRuntime.Call c){v.collideObjects(c);}public void timeWarp(CdPlayerSemanticRuntime.Call c){v.timeWarp(c);}
  public CdPlayerCharge.Result moveGroundCharge(CdPlayerSemanticRuntime.Call c,CdPlayerCharge.State s,CdPlayerCharge.Input i){return v.moveGroundCharge(c,s,i);}public CdPlayerCharge.Result moveRollCharge(CdPlayerSemanticRuntime.Call c,CdPlayerCharge.State s,CdPlayerCharge.Input i){return v.moveRollCharge(c,s,i);}public CdPlayerCharge.Result startRoll(CdPlayerSemanticRuntime.Call c,CdPlayerCharge.State s,CdPlayerCharge.Body b){return v.startRoll(c,s,b);}public CdPlayerBody.LevelContext level(CdPlayerSemanticRuntime.Call c){return v.level(c);}public void storeLevel(CdPlayerSemanticRuntime.Call c,CdPlayerBody.LevelField f,int n){v.storeLevel(c,f,n);}public void spawnGameOver(CdPlayerSemanticRuntime.Call c){v.spawnGameOver(c);}public void restartSoundFlag(CdPlayerSemanticRuntime.Call c){v.restartSoundFlag(c);}public void resetSavedObjectFlags(CdPlayerSemanticRuntime.Call c){v.resetSavedObjectFlags(c);}public void completed(CdPlayerSemanticRuntime.Call c,CdPlayerBody.Boundary b){v.completed(c,b);}
 }
}
